import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { get, getAll } from '@vercel/edge-config';
// Dub's Vercel calls (apps/web/lib/api/domains/*, apps/web/lib/edge-config/*): fetch to api.vercel.com with the
// env names Dub reads, and the unchanged @vercel/edge-config on the project's EDGE_CONFIG connection string.
for (const name of ['VERCEL_API_KEY', 'TEAM_ID_VERCEL', 'VERCEL_PROJECT_ID', 'EDGE_CONFIG', 'EDGE_CONFIG_ID']) if (!process.env[name]) throw new Error(`${name} is not set`);
const headers = { Authorization: `Bearer ${process.env.VERCEL_API_KEY}`, 'Content-Type': 'application/json' };
const team = process.env.TEAM_ID_VERCEL;
const project = process.env.VERCEL_PROJECT_ID;
const receiptFile = 'vercel-records.json';
const apexOf = (domain) => domain.split('.').slice(-2).join('.');
// get-domain-response.ts getVercelDomainResponse
const getVercelDomainResponse = (domain) => fetch(`https://api.vercel.com/v9/projects/${project}/domains/${domain.toLowerCase()}?teamId=${team}`, { method: 'GET', headers }).then((res) => res.json());
// get-config-response.ts getVercelConfigResponse
const getVercelConfigResponse = (domain) => fetch(`https://api.vercel.com/v6/domains/${domain.toLowerCase()}/config?teamId=${team}`, { method: 'GET', headers }).then((res) => res.json());
// add-domain-vercel.ts addDomainToVercel: the apex's wildcard first, then the domain
async function addDomainToVercel(domain) {
  domain = domain.toLowerCase();
  const apexDomain = apexOf(domain);
  if (apexDomain !== domain) {
    const wildcardResponse = await getVercelDomainResponse(`*.${apexDomain}`);
    if (wildcardResponse.verified) return wildcardResponse;
  }
  return fetch(`https://api.vercel.com/v10/projects/${project}/domains?teamId=${team}`, { method: 'POST', headers, body: JSON.stringify({ name: domain }) }).then((res) => res.json());
}
// edge-config/update.ts updateConfig: the item read with the SDK, the value added, the item written back
async function updateConfig({ key, value }) {
  const existingData = await get(key);
  const newData = Array.from(new Set([...existingData, value]));
  return fetch(`https://api.vercel.com/v1/edge-config/${process.env.EDGE_CONFIG_ID}/items?teamId=${team}`, { method: 'PATCH', headers, body: JSON.stringify({ items: [{ operation: 'update', key, value: newData }] }) });
}
const DOMAIN = 'www.alicebakes.com';
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const domain = await getVercelDomainResponse(DOMAIN);
  assert.equal(domain.name, DOMAIN);
  assert.equal(domain.projectId, saved.project);
  assert.equal(domain.verified, true);
  const blocked = await get('domains');
  assert.deepEqual(blocked, ['phish-bank.com', 'free-gift-cards.site']);
  console.log(JSON.stringify({ retained: true, domain: domain.name, blocked }));
} else {
  // the blocklists Dub keeps in Edge Config, written once by the app
  const seeded = await fetch(`https://api.vercel.com/v1/edge-config/${process.env.EDGE_CONFIG_ID}/items?teamId=${team}`, { method: 'PATCH', headers, body: JSON.stringify({ items: [
    { operation: 'upsert', key: 'domains', value: ['phish-bank.com'] }, { operation: 'upsert', key: 'terms', value: ['gift-card'] }, { operation: 'upsert', key: 'whitelistedDomains', value: [] },
  ] }) });
  assert.equal((await seeded.json()).status, 'ok');
  // isBlacklistedDomain: the three lists in one read
  const { domains, terms, whitelistedDomains } = await getAll(['domains', 'terms', 'whitelistedDomains']);
  assert.deepEqual([domains, terms, whitelistedDomains], [['phish-bank.com'], ['gift-card'], []]);
  assert.equal(domains.includes(DOMAIN) || terms.some((t) => DOMAIN.includes(t)), false);
  // a customer's domain added to the project: no other account holds its apex, so it is verified at once
  const added = await addDomainToVercel(DOMAIN);
  assert.equal(added.name, DOMAIN);
  assert.equal(added.apexName, 'alicebakes.com');
  assert.equal(added.projectId, project);
  assert.equal(added.verified, true);
  // its configuration: misconfigured until the customer sets the record Vercel recommends
  const config = await getVercelConfigResponse(DOMAIN);
  assert.equal(config.misconfigured, true);
  assert.ok(config.recommendedCNAME?.[0]?.value, 'a recommended CNAME is shown');
  // a phishing domain banned: the item read with the SDK and written back with it added
  const banned = await updateConfig({ key: 'domains', value: 'free-gift-cards.site' });
  assert.equal(banned.status, 200);
  const saved = { project, domain: added.name };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ added: added.name, cname: config.recommendedCNAME[0].value, ...saved }));
}
